import { afterAll, beforeAll, expect, test } from "bun:test"
import { chmod, mkdtemp, rm, writeFile } from "node:fs/promises"
import { tmpdir } from "node:os"
import { join } from "node:path"
import plugin from "../src/index.js"

interface Tool {
  name: string
  execute: (input: unknown, context: { sessionID: string }) => Promise<{ output: unknown; content: string }>
}

interface Strategy {
  create: (input: { sourceDirectory: string; directory: string }, context: { signal: AbortSignal }) => Promise<{ directory: string }>
  remove: (input: { directory: string; force: boolean }, context: { signal: AbortSignal }) => Promise<void>
}

let temp: string

beforeAll(async () => {
  temp = await mkdtemp(join(tmpdir(), "opencode-rift-plugin-"))
})

afterAll(async () => {
  await rm(temp, { recursive: true, force: true })
})

async function fakeRift(failure?: { command: string; hook: string; path: string }) {
  const executable = join(temp, `rift-${Math.random().toString(36).slice(2)}`)
  await writeFile(
    executable,
    `#!/usr/bin/env node
const failure = ${JSON.stringify(failure ?? null)}
let input = ""
process.stdin.on("data", (chunk) => (input += chunk))
process.stdin.on("end", () => {
  const request = JSON.parse(input)
  if (failure && request.command === failure.command) {
    process.stderr.write("ERR_PNPM_FETCH_401 token expired\\n")
    const error = { code: "hook_failed", message: failure.hook + " hook failed", path: failure.path, hook: failure.hook, committed: true }
    process.stdout.write(JSON.stringify({ status: "error", error }))
    return
  }
  const value = request.command === "create" ? request.into + "/" + request.name : request.command === "list" ? [] : null
  process.stdout.write(JSON.stringify({ status: "ok", value }))
})
`,
  )
  await chmod(executable, 0o755)
  return executable
}

async function setup(executable: string) {
  const tools = new Map<string, Tool>()
  let strategy: Strategy | undefined
  const signal = new AbortController().signal
  const ctx = {
    options: { executable },
    session: {
      get: async () => ({ projectID: "project", location: { directory: "/project" } }),
    },
    worktree: {
      transform: async (callback: (editor: { add: (definition: Strategy) => void }) => void) => {
        callback({ add: (definition) => (strategy = definition) })
      },
      list: async () => [{ directory: "/project" }],
      create: (input: { from: string; name: string }) =>
        strategy!.create({ sourceDirectory: input.from, directory: `/worktrees/${input.name}` }, { signal }),
      remove: (input: { directory: string; force: boolean }) => strategy!.remove(input, { signal }),
    },
    tool: {
      transform: async (callback: (editor: { namespace: () => void; add: (tool: Tool) => void }) => void) => {
        callback({ namespace: () => {}, add: (tool) => tools.set(tool.name, tool) })
      },
    },
  }
  await plugin.setup(ctx as never)
  return tools
}

test("rift.create reports a failed postcreate hook to the agent", async () => {
  const tools = await setup(await fakeRift({ command: "create", hook: "postcreate", path: "/worktrees/task" }))
  const result = await tools.get("create")!.execute({ name: "task" }, { sessionID: "session" })
  expect(result.output).toEqual({
    directory: "/worktrees/task",
    warning: "postcreate hook failed: ERR_PNPM_FETCH_401 token expired",
  })
  expect(result.content).toBe(
    "Created /worktrees/task. Use opencode.session_move to move a session into it.\n\n" +
      "Warning: postcreate hook failed: ERR_PNPM_FETCH_401 token expired",
  )
})

test("rift.remove reports a failed postremove hook to the agent", async () => {
  const tools = await setup(await fakeRift({ command: "remove", hook: "postremove", path: "/rifts/.trash/task" }))
  const result = await tools.get("remove")!.execute({ directory: "/worktrees/task" }, { sessionID: "session" })
  expect(result.output).toEqual({
    directory: "/worktrees/task",
    warning: "postremove hook failed: ERR_PNPM_FETCH_401 token expired",
  })
  expect(result.content).toBe(
    "Removed /worktrees/task.\n\nWarning: postremove hook failed: ERR_PNPM_FETCH_401 token expired",
  )
})

test("successful hooks add no warning", async () => {
  const tools = await setup(await fakeRift())
  const result = await tools.get("create")!.execute({ name: "task" }, { sessionID: "session" })
  expect(result).toEqual({
    output: { directory: "/worktrees/task" },
    content: "Created /worktrees/task. Use opencode.session_move to move a session into it.",
  })
})

#![cfg(unix)]
mod support;

use std::fs;
use support::filesystem::{CliFixture, supported_linux_filesystem_tests_required};

#[test]
fn shell_cwd_survives_hook_output_and_failure() {
    // `init` probes for copy-on-write support, so this needs APFS or one of
    // the prepared Linux filesystems in CI.
    if !(cfg!(target_os = "macos") || supported_linux_filesystem_tests_required()) {
        return;
    }
    let fixture = CliFixture::current_filesystem(".rift-cli-shell-cwd-");
    let source = fixture.root().join("source");
    fs::create_dir_all(&source).unwrap();
    fs::write(
        source.join(".rift.toml"),
        "version = 1\n[[hooks.postcreate]]\nrun = \"printf hook-output\"\n",
    )
    .unwrap();
    fixture.success(&source, ["init", "--here"]);

    let create = fixture.success(&source, ["--shell-cwd", "create", "--name", "child"]);
    let child = create.single_stdout_path();
    assert_eq!(
        child,
        fs::canonicalize(fixture.root())
            .unwrap()
            .join(".rifts/source/child")
    );
    assert!(create.stderr.contains("hook-output"));

    fs::write(
        child.join(".rift.toml"),
        "version = 1\n[[hooks.postremove]]\nrun = \"exit 23\"\n",
    )
    .unwrap();
    let remove = fixture.failure(&child, ["--shell-cwd", "remove"]);
    assert_eq!(
        remove.single_stdout_path(),
        fs::canonicalize(&source).unwrap()
    );
    assert!(!child.exists());
}

#[cfg(target_os = "linux")]
mod support;

#[cfg(target_os = "linux")]
use std::ffi::{OsStr, OsString};
#[cfg(target_os = "linux")]
use std::fs;
#[cfg(target_os = "linux")]
use std::path::{Path, PathBuf};
#[cfg(target_os = "linux")]
use support::filesystem::{
    CliFixture, assert_different_filesystems, assert_registry_empty,
    supported_linux_filesystem_tests_required, unsupported_linux_filesystem_tests_required,
};

#[cfg(target_os = "linux")]
#[test]
fn supported_filesystem_cli_round_trip() {
    if !supported_linux_filesystem_tests_required() {
        return;
    }
    let fixture = CliFixture::current_filesystem(".rift-cli-supported-");
    let source = fixture.root().join("source");
    create_workspace(&source);

    let init = fixture.success(
        fixture.root(),
        [os("init"), os(source.as_os_str()), os("--here")],
    );
    assert!(init.stdout.is_empty());
    assert!(source.join(".rift").exists());

    let child = fixture
        .success(&source, ["create", "--name", "child"])
        .single_stdout_path();
    assert_eq!(child, fixture.root().join(".rifts/source/child"));
    assert_workspace_copy(&child);

    let custom_parent = fixture.root().join("custom-storage");
    let custom = fixture
        .success(
            &source,
            [
                os("create"),
                os("--name"),
                os("custom"),
                os("--into"),
                os(custom_parent.as_os_str()),
            ],
        )
        .single_stdout_path();
    assert_eq!(custom, custom_parent.join("custom"));
    assert_workspace_copy(&custom);

    assert_paths_unordered(
        fixture.success(&source, ["list"]).stdout_paths(),
        &[child.clone(), custom.clone()],
    );
    assert_eq!(
        fixture
            .success(&source, [os("ancestors"), os(custom.as_os_str())])
            .stdout_paths(),
        vec![source.clone()]
    );

    let external = tempfile::TempDir::new().unwrap();
    assert_different_filesystems(&source, external.path());
    let external_parent = external.path().join("external-storage");
    let failed = fixture.failure(
        &source,
        [
            os("create"),
            os("--name"),
            os("external"),
            os("--into"),
            os(external_parent.as_os_str()),
        ],
    );
    assert!(failed.stderr.contains("copy-on-write cloning unavailable"));
    assert!(!external_parent.join("external").exists());

    let remove = fixture.success(&source, [os("remove"), os(child.as_os_str())]);
    assert!(remove.stdout.is_empty());
    assert!(!child.exists());
    assert_eq!(
        fixture.success(&source, ["list"]).stdout_paths(),
        vec![custom.clone()]
    );

    let removed = fixture.success(&source, ["gc"]).stdout_paths();
    assert_eq!(removed.len(), 1);
    assert!(removed[0].starts_with(fixture.root().join(".rifts/source/.trash")));
    assert!(!removed[0].exists());
    assert!(!fixture.default_database().exists());
}

#[cfg(target_os = "linux")]
#[test]
fn unsupported_filesystem_cli_fails_closed() {
    if !unsupported_linux_filesystem_tests_required() {
        return;
    }
    let fixture = CliFixture::current_filesystem(".rift-cli-unsupported-");
    let source = fixture.root().join("source");
    create_workspace(&source);

    let init = fixture.failure(
        fixture.root(),
        [os("init"), os(source.as_os_str()), os("--here")],
    );
    assert!(init.stdout.is_empty());
    assert!(init.stderr.contains("copy-on-write cloning unavailable"));
    assert!(!source.join(".rift").exists());
    assert!(!fixture.root().join(".rifts").exists());
    assert_no_reflink_probe_files(&source);
    assert_registry_empty(fixture.database());

    let create = fixture.failure(&source, ["create", "--name", "child"]);
    assert!(create.stderr.contains("no initialized workspace found"));
    assert!(!fixture.root().join(".rifts/source/child").exists());
    assert!(!fixture.default_database().exists());
    assert_registry_empty(fixture.database());
}

#[cfg(target_os = "linux")]
fn create_workspace(source: &Path) {
    fs::create_dir_all(source.join("nested")).unwrap();
    fs::write(source.join("nested/file.txt"), "hello from cli e2e").unwrap();
    fs::write(source.join("untracked.txt"), "kept").unwrap();
}

#[cfg(target_os = "linux")]
fn assert_workspace_copy(path: &Path) {
    assert_eq!(
        fs::read_to_string(path.join("nested/file.txt")).unwrap(),
        "hello from cli e2e"
    );
    assert_eq!(
        fs::read_to_string(path.join("untracked.txt")).unwrap(),
        "kept"
    );
    assert!(path.join(".rift").exists());
}

#[cfg(target_os = "linux")]
fn assert_no_reflink_probe_files(path: &Path) {
    assert!(
        fs::read_dir(path)
            .unwrap()
            .map(|entry| entry.unwrap().file_name())
            .all(|name| !name.to_string_lossy().starts_with(".rift-reflink-probe"))
    );
}

#[cfg(target_os = "linux")]
fn assert_paths_unordered(mut actual: Vec<PathBuf>, expected: &[PathBuf]) {
    let mut expected = expected.to_vec();
    actual.sort();
    expected.sort();
    assert_eq!(actual, expected);
}

#[cfg(target_os = "linux")]
fn os(arg: impl AsRef<OsStr>) -> OsString {
    arg.as_ref().to_os_string()
}

import { describe, expect, test } from "bun:test"
import { RpcError } from "../src/command.js"
import { makeStrategy } from "../src/strategy.js"

function fixture() {
  const calls: object[] = []
  const children = new Map<string, string[]>([
    ["/project", ["/rifts/one"]],
    ["/rifts/one", ["/rifts/two"]],
    ["/rifts/two", []],
  ])
  const call = async (_executable: string, request: object) => {
    calls.push(request)
    if (!("command" in request)) throw new Error("missing command")
    if (request.command === "create" && "into" in request && "name" in request)
      return `${request.into}/${request.name}`
    if (request.command === "descendants") return ["/rifts/two", "/rifts/one"]
    if (request.command === "list" && "of" in request && typeof request.of === "string")
      return children.get(request.of) ?? []
    return null
  }
  return { calls, children, strategy: makeStrategy({ copyAll: false }, { rpc: call }) }
}

const context = { signal: new AbortController().signal }

describe("Rift workspace strategy", () => {
  test("validates plugin options", () => {
    expect(() => makeStrategy({ executable: "" })).toThrow("non-empty")
    expect(() => makeStrategy({ copyAll: "yes" })).toThrow("boolean")
    expect(() => makeStrategy({ hooks: "yes" })).toThrow("boolean")
    expect(() => makeStrategy({ database: "" })).toThrow("non-empty")
    expect(() => makeStrategy({ unknown: true })).toThrow("Unknown Rift option")
  })

  test("creates at OpenCode's suggested destination", async () => {
    const { calls, strategy } = fixture()
    await expect(
      strategy.create({ sourceDirectory: "/project", directory: "/worktrees/task" }, context),
    ).resolves.toEqual({ directory: "/worktrees/task" })
    expect(calls).toEqual([
      {
        database: undefined,
        command: "create",
        from: "/project",
        into: "/worktrees",
        name: "task",
        copyAll: false,
        hooks: true,
      },
    ])
  })

  test("discovers descendants and removes only leaves", async () => {
    const { calls, children, strategy } = fixture()
    await expect(strategy.list("/project", context)).resolves.toEqual([
      { directory: "/project", type: "root" },
      { directory: "/rifts/two", type: "worktree" },
      { directory: "/rifts/one", type: "worktree" },
    ])
    await expect(strategy.remove({ directory: "/rifts/one", force: true }, context)).rejects.toThrow(
      "Remove this Rift's child workspaces first",
    )
    children.delete("/rifts/two")
    await strategy.remove({ directory: "/rifts/two", force: false }, context)
    expect(calls.at(-1)).toEqual({
      database: undefined,
      command: "remove",
      at: "/rifts/two",
      hooks: true,
    })
  })

  test("explains initialization failures", async () => {
    const failing = (code: string) =>
      makeStrategy(
        {},
        {
          rpc: async () => {
            throw new RpcError({ code, message: `${code} at /project`, path: "/project" })
          },
        },
      )
    const create = (code: string) =>
      failing(code).create({ sourceDirectory: "/project", directory: "/worktrees/task" }, context)
    await expect(create("workspace_not_initialized")).rejects.toThrow(
      "Rift source is not initialized; run `rift init` from the project root first",
    )
    await expect(create("initialization_required")).rejects.toThrow(
      "This Rift workspace must be initialized first; run `rift init` from its root folder",
    )
    await expect(create("missing_marker")).rejects.toThrow(
      "This Rift workspace is missing its `.rift` marker; run `rift init` to restore it",
    )
    await expect(create("hook_failed")).rejects.toThrow("hook_failed at /project")
  })

  test("keeps OpenCode inventory consistent after post-hook failures", async () => {
    const warnings: Array<{ directory: string; message: string }> = []
    const strategy = makeStrategy(
      {},
      {
        warning: (warning) => warnings.push(warning),
        rpc: async (_executable, request) => {
          if ("command" in request && request.command === "create")
            throw new RpcError({
              code: "hook_failed",
              message: "postcreate failed",
              path: "/worktrees/task",
              hook: "postcreate",
              committed: true,
            })
          if ("command" in request && request.command === "remove")
            throw new RpcError({
              code: "hook_failed",
              message: "postremove failed",
              path: "/rifts/.trash/task",
              hook: "postremove",
              committed: true,
            })
          return []
        },
      },
    )

    await expect(
      strategy.create({ sourceDirectory: "/project", directory: "/worktrees/task" }, context),
    ).resolves.toEqual({ directory: "/worktrees/task" })
    await strategy.remove({ directory: "/worktrees/task", force: false }, context)
    expect(warnings).toEqual([
      { directory: "/worktrees/task", message: "postcreate failed" },
      { directory: "/worktrees/task", message: "postremove failed" },
    ])
  })
})

use crate::test_support::linux_extents::{assert_shared_extents_when_reliable, is_btrfs_subvolume};
use crate::{Create, Error, InitOutcome, Manager};
